"""Quality-control checks for a single time series sample.

The public entry point :func:`qc_series` inspects a raw sample (values,
timestamps and a pair of bounds) and returns a report describing gaps,
spike deviations, a trend and an overall verdict.
"""

from __future__ import annotations

TREND_TOLERANCE = 5

REQUIRED_FIELDS = ("values", "timestamps", "expected_step", "hard_limit")

# Deviation thresholds (inclusive) that a sample must reach before it is
# classified as a spike, and the score attributed to each class.
_MINOR_DEVIATION = 3
_MODERATE_DEVIATION = 6
_SEVERE_DEVIATION = 12

LABELS = ("clean", "minor", "moderate", "severe", "invalid")

# Score awarded per sample, keyed by its spike label.
_SCORE_BY_LABEL = {"clean": 0, "minor": 3, "moderate": 10, "severe": 25, "invalid": 100}

# Reverse lookup from a sample's score back to its label.
_LABEL_BY_SCORE = {score: label for label, score in _SCORE_BY_LABEL.items()}

