"""Quality-control checks for a single time series sample.

The public entry point :func:`qc_series` inspects a raw sample (values,
timestamps and a pair of bounds) and returns a report describing gaps,
spike deviations, a trend and an overall verdict.
"""

from __future__ import annotations

TREND_TOLERANCE = 5

REQUIRED_FIELDS = ("values", "timestamps", "expected_step", "hard_limit")

# Deviation thresholds (inclusive) that a sample must reach before it is
# classified as a spike, and the score attributed to each class.
_MINOR_DEVIATION = 3
_MODERATE_DEVIATION = 6
_SEVERE_DEVIATION = 12

LABELS = ("clean", "minor", "moderate", "severe", "invalid")

# Score awarded per sample, keyed by its spike label.
_SCORE_BY_LABEL = {"clean": 0, "minor": 3, "moderate": 10, "severe": 25, "invalid": 100}

# Reverse lookup from a sample's score back to its label.
_LABEL_BY_SCORE = {score: label for label, score in _SCORE_BY_LABEL.items()}

_VERDICT_CODES = frozenset((0, 3, 10, 25, 100))


def qc_series(raw: object) -> dict:
    """Run the full QC pipeline against a raw sample and return a report."""
    error = _validate_input(raw)
    if error is not None:
        return {"ok": False, "error": error}

    values = raw["values"]
    timestamps = raw["timestamps"]
    gaps = _count_gaps(timestamps, raw["expected_step"])
    deviations = _deviations(values)
    labels, total, worst = classify_spikes(deviations, raw["hard_limit"])

    return {
        "ok": True,
        "labels": labels,
        "gaps": gaps,
        "score": total,
        "verdict": _verdict(total),
        "counts": _label_counts(labels),
        "trend": _trend(values),
        "streak": _longest_run(labels),
        "line": _summary_line(len(values), gaps, worst, total),
    }


def _validate_input(raw: object) -> str | None:
    """Return a human-readable error message, or None when the input is valid."""
    if not isinstance(raw, dict):
        return "malformed input"
    for key in REQUIRED_FIELDS:
        if key not in raw:
            return "missing field"

    series_error = _series_error(raw["values"], raw["timestamps"])
    if series_error is not None:
        return series_error
    return _bounds_error(raw["expected_step"], raw["hard_limit"])


def _series_error(values: object, timestamps: object) -> str | None:
    """Check that the value and timestamp series are well-formed."""
    if not isinstance(values, list) or len(values) == 0:
        return "bad values"
    if not isinstance(timestamps, list) or len(timestamps) != len(values):
        return "bad timestamps"

    for value, stamp in zip(values, timestamps):
        if not isinstance(value, int) or not isinstance(stamp, int):
            return "bad sample"
    return _order_error(timestamps)


def _order_error(timestamps: list) -> str | None:
    """Ensure timestamps are strictly increasing."""
    for index in range(1, len(timestamps)):
        if timestamps[index] <= timestamps[index - 1]:
            return "unordered timestamps"
    return None


def _bounds_error(expected_step: object, hard_limit: object) -> str | None:
    """Ensure the configured bounds are positive integers."""
    if not isinstance(expected_step, int) or expected_step <= 0:
        return "bad step"
    if not isinstance(hard_limit, int) or hard_limit <= 0:
        return "bad limit"
    return None


def _count_gaps(timestamps: list, expected_step: int) -> int:
    """Count intervals between consecutive timestamps exceeding the expected step."""
    return sum(
        1
        for index in range(1, len(timestamps))
        if timestamps[index] - timestamps[index - 1] > expected_step
    )


def _deviations(values: list) -> list:
    """Absolute difference of each value from its local window median."""
    return [abs(value - _window_median(values, index)) for index, value in enumerate(values)]


def _window_median(values: list, index: int) -> int:
    """Median of the sample and its immediate neighbours (edges mirror themselves)."""
    previous = values[index - 1] if index > 0 else values[index]
    following = values[index + 1] if index + 1 < len(values) else values[index]
    return _median3(previous, values[index], following)


def _median3(a: int, b: int, c: int) -> int:
    """Return the median of three integers without allocating a list."""
    if a > b:
        a, b = b, a
    if b > c:
        b, c = c, b
    if a > b:
        a, b = b, a
    return b


def _grade(deviation: int, hard_limit: int) -> tuple[str, int]:
    """Classify a single deviation into a (label, score) pair."""
    if deviation >= hard_limit:
        return "invalid", 100
    if deviation >= _SEVERE_DEVIATION:
        return "severe", 25
    if deviation >= _MODERATE_DEVIATION:
        return "moderate", 10
    if deviation >= _MINOR_DEVIATION:
        return "minor", 3
    return "clean", 0


def classify_spikes(deviations: list, hard_limit: int) -> tuple:
    """Classify a series of deviations; return labels, total score and worst score."""
    labels: list[str] = []
    total = 0
    worst = 0
    for deviation in deviations:
        label, score = _grade(deviation, hard_limit)
        labels.append(label)
        total += score
        if score > worst:
            worst = score
    return labels, total, worst


def _worst_label(worst_score: int) -> str:
    """Map a worst score back to its human-readable label."""
    return _LABEL_BY_SCORE.get(worst_score, "clean")


def _label_counts(labels: list) -> dict:
    """Count how many samples fell into each spike label."""
    counts = {label: 0 for label in LABELS}
    for label in labels:
        counts[label] += 1
    return counts


def _trend(values: list) -> str:
    """Describe the overall direction of the series from its endpoints."""
    delta = values[-1] - values[0]
    if delta > TREND_TOLERANCE:
        return "rising"
    if delta < -TREND_TOLERANCE:
        return "falling"
    return "stable"


def _longest_run(labels: list) -> int:
    """Longest consecutive run of non-clean samples."""
    longest = 0
    current = 0
    for label in labels:
        if label == "clean":
            current = 0
        else:
            current += 1
            if current > longest:
                longest = current
    return longest


def _verdict(total: int) -> str:
    """Derive an overall verdict from the accumulated score."""
    if total >= 100:
        return "fail"
    if total >= 25:
        return "warn"
    return "pass"


def _summary_line(count: int, gaps: int, worst_score: int, total: int) -> str:
    """Render the one-line QC summary."""
    return f"n={count};gaps={gaps};worst={_worst_label(worst_score)};score={total}"

